export function countriesFor(era: Era, year: number): CountryId[] {
  if (era.id !== 'war') return era.world
  // 中国固定在首位，其余按当年与中国关系的密切程度排列。
  const orders: Record<number, CountryId[]> = {
    1937: ['china', 'japan', 'korea', 'usa', 'ussr', 'germany', 'britain', 'france'],
    1938: ['china', 'japan', 'ussr', 'usa', 'britain', 'france', 'germany'],
    1939: ['china', 'japan', 'ussr', 'usa', 'britain', 'france', 'germany'],
    1940: ['china', 'japan', 'usa', 'ussr', 'britain', 'france', 'germany'],
    1941: ['china', 'japan', 'usa', 'britain', 'ussr', 'france', 'germany'],
    1942: ['china', 'japan', 'usa', 'britain', 'ussr', 'france', 'germany'],
    1943: ['china', 'japan', 'usa', 'britain', 'ussr', 'france', 'germany'],
    1944: ['china', 'japan', 'usa', 'britain', 'ussr', 'france', 'germany'],
    1945: ['china', 'japan', 'usa', 'ussr', 'britain', 'france', 'germany'],
  }
  return orders[year] ?? era.world
}
export function formatYear(year: number) { return year < 0 ? `前 ${Math.abs(year)}` : `${year}` }
export function plainText(text: string) { return text.replace(/\[\[[^\]|]+\|([^\]]+)\]\]/g, '$1') }
export function eventDay(event: HistoryEvent) {
  return event.day ?? Number(event.date.match(/(?:月|[.．])(\d{1,2})(?:日|[—–～]|$)/)?.[1] ?? 0)
}
export function undatedPeriod(event: HistoryEvent) {
  if (/月初|上旬|初旬/.test(event.date)) return '月初'
  if (/中旬|月中/.test(event.date)) return '中旬'
  if (/下旬|月末|月底/.test(event.date)) return '下旬'
  return '月内'
}
// An undated record's display position is not its historical occurrence date.
export function eventDisplayDay(event: HistoryEvent) {
  if (event.precision !== 'month') return eventDay(event)
  const period = undatedPeriod(event)
  if (period === '月初') return 1
  if (period === '中旬') return 10
  if (period === '下旬') return new Date(event.year, event.month, 0).getDate()
  return 15
}
